    Suitable for the time-machine commits list.
    """
    result = _run_git(repo_path, [
        "log",
        f"-{max_commits}",
        "--pretty=format:%H|%an|%ad|%s",
        "--date=short",
    ])

    if result.returncode != 0:
        return {
            "status": "error",
            "message": result.stderr.strip() or "git log failed",
        }

    commits = []
    for line in result.stdout.splitlines():
        parts = line.split("|", 3)
        if len(parts) == 4:
            commits.append({
                "commit":  parts[0],
                "author":  parts[1],
                "date":    parts[2],
                "message": parts[3],
            })

    if not commits:
        return {
            "status":  "empty",
            "message": "No commits found in this repository.",
            "commits": [],
        }

    return {
        "status":       "success",
        "commit_count": len(commits),
        "commits":      commits,
    }


def get_files_changed_in_commit(repo_path: str, commit_hash: str) -> dict:
    """
    Return the list of files that were added, modified, or deleted in a
    specific commit, along with the change type (A/M/D/R...).
    """
    result = _run_git(repo_path, [
        "diff-tree",
        "--no-commit-id",
        "-r",
        "--name-status",
        commit_hash,
    ])

    if result.returncode != 0:
        return {
            "status":  "error",
            "commit":  commit_hash,
            "message": result.stderr.strip() or "git diff-tree failed",
        }

    files = []
    for line in result.stdout.splitlines():
        parts = line.split("\t", 1)
        if len(parts) == 2:
            status, path = parts
            files.append({"status": status.strip(), "file": path.strip()})

    return {
        "status":       "success",
        "commit":       commit_hash,
        "files_changed": files,
    }


def get_file_at_commit(repo_path: str, commit_hash: str, file_path: str) -> dict:
    """
    Return the content of a specific file as it existed at *commit_hash*.
    """
    # git show <commit>:<path>
    result = _run_git(repo_path, [
        "show",
        f"{commit_hash}:{file_path}",
    ])

    if result.returncode != 0:
        stderr = result.stderr.strip()
        if "does not exist" in stderr or "exists on disk" in stderr or "Path" in stderr:
            return {
                "status":  "not_found",
                "commit":  commit_hash,
                "file":    file_path,
                "message": f"File '{file_path}' did not exist at commit {commit_hash[:8]}.",
            }
        return {
            "status":  "error",
            "commit":  commit_hash,
            "file":    file_path,
            "message": stderr or "git show failed",
        }

    return {
        "status":  "success",
        "commit":  commit_hash,
        "file":    file_path,
        "content": result.stdout,
    }


def get_diff_between_commits(repo_path: str, from_commit: str, to_commit: str) -> dict:
    """
    Return the unified diff between two commits.
    Includes a structured per-file summary alongside the raw diff.
    """
    result = _run_git(repo_path, [
        "diff",
        from_commit,
        to_commit,
    ])

    if result.returncode != 0:
        return {
            "status":  "error",
            "from":    from_commit,
            "to":      to_commit,
            "message": result.stderr.strip() or "git diff failed",
        }

    # Build a lightweight per-file summary from the diff
    files_changed = []
    current_file  = None
    added = deleted = 0

    for line in result.stdout.splitlines():
        if line.startswith("diff --git"):
            if current_file:
                files_changed.append({
                    "file":    current_file,
                    "added":   added,
                    "deleted": deleted,
                })
            parts = line.split(" b/", 1)
            current_file = parts[1] if len(parts) == 2 else line
            added = deleted = 0
        elif line.startswith("+") and not line.startswith("+++"):
            added += 1
        elif line.startswith("-") and not line.startswith("---"):
            deleted += 1

    if current_file:
        files_changed.append({
            "file":    current_file,
            "added":   added,
            "deleted": deleted,
        })

    return {
        "status":        "success",
        "from":          from_commit,
        "to":            to_commit,
        "files_changed": files_changed,
        "raw_diff":      result.stdout,
    }


def get_file_history(repo_path: str, file_path: str, max_commits: int = 50) -> dict:
    """
    Return the commit history for a single file.
    """
    result = _run_git(repo_path, [
        "log",
        f"-{max_commits}",
        "--pretty=format:%H|%an|%ad|%s",
        "--date=short",
        "--follow",
        "--",
        file_path,
    ])

    if result.returncode != 0:
        return {
            "status":  "error",
            "file":    file_path,
            "message": result.stderr.strip() or "git log failed",
        }

    commits = []
    for line in result.stdout.splitlines():
        parts = line.split("|", 3)
        if len(parts) == 4:
            commits.append({
                "commit":  parts[0],
                "author":  parts[1],
                "date":    parts[2],
                "message": parts[3],
            })

    if not commits:
        return {
            "status":  "not_found",
            "file":    file_path,
            "message": f"No commits found for '{file_path}'. "
                       "The file may not exist or has never been committed.",
            "commits": [],
        }

    return {
        "status":       "success",
        "file":         file_path,
        "commit_count": len(commits),
        "commits":      commits,
    }

